effect.shader:
// Medir a interpolação no AE e trocar se for a trilinear (ver o cabeçalho).
const bool TETRAEDRICA = true;

void main() {
    ivec2 T = textureSize(inputImg, 0);
    vec4 fonte = texelFetch(inputImg, ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0)), 0);
    vec3 c = fonte.rgb;

    // Basic Correction: o LUT de entrada, antes de tudo.
    c = lutDeEntradaAplicar(c, TETRAEDRICA);

    // Creative: o Look, misturado pela Intensidade.
    if (lookTipo != 0) {
        vec3 comLook = lookAplicar(c, TETRAEDRICA);
        c = mix(c, comLook, clamp(intensidade, 0.0, 200.0) / 100.0);
    }

    fragColor = vec4(clamp(c, 0.0, 1.0), fonte.a);
}
